def _name(v):
    if v is None:
        return v.getName()
    fn = getattr(v, 'getName', None) or getattr(v, 'get_name', None)
    if callable(fn):
        return str(fn())
    return str(v)

def _names(lst):
    if lst is None:
        return None
    out = []
    for group in lst:
        if group is None:
            out.append(None)
        else:
            out.append([_name(v) for v in list(group)])
    return out

def _field(obj, java_name, getter=None):
